mapper.update:
UPDATE comment SET like_count = like_count + CASE id
WHEN #{commentId} THEN #{increment}
END, updated_at = NOW() WHERE id IN
#{commentId}

mapper.select:
SELECT c.id, c.gif_id, c.user_id, c.content, c.like_count, c.created_at, u.nickname, u.avatar FROM comment c INNER JOIN users u ON c.user_id = u.id WHERE c.gif_id = #{gifId} AND c.root_comment_id IS NULL AND c.status = 1
AND c.created_at > #{cursor}
ORDER BY c.created_at ASC LIMIT #{limit}

SELECT root_comment_id, COUNT(*) AS child_count FROM comment WHERE root_comment_id IN
#{id}
AND status = 1 GROUP BY root_comment_id

SELECT c.id, c.gif_id, c.user_id, c.parent_id, c.parent_user_id, c.root_comment_id, c.content, c.like_count, c.created_at, u.nickname, u.avatar, pu.nickname AS parent_nickname FROM comment c INNER JOIN users u ON c.user_id = u.id LEFT JOIN users pu ON c.parent_user_id = pu.id WHERE c.root_comment_id = #{rootCommentId} AND c.status = 1
AND c.created_at > #{cursor}
ORDER BY c.created_at ASC LIMIT #{limit}

SELECT c.id, c.gif_id, c.user_id, c.content, c.like_count, c.created_at, u.nickname, u.avatar FROM comment c INNER JOIN users u ON c.user_id = u.id WHERE c.id IN
#{id}
AND c.status = 1

SELECT c.id, c.gif_id, c.user_id, c.parent_id, c.parent_user_id, c.root_comment_id, c.content, c.like_count, c.created_at, u.nickname, u.avatar, pu.nickname AS parent_nickname FROM comment c INNER JOIN users u ON c.user_id = u.id LEFT JOIN users pu ON c.parent_user_id = pu.id WHERE c.id IN
#{id}
AND c.status = 1

SELECT c.id AS comment_id, c.gif_id, c.user_id, c.content, c.like_count, c.created_at, u.nickname, u.avatar FROM comment c INNER JOIN users u ON c.user_id = u.id WHERE c.id IN
#{id}
AND c.status = 1
